import{_ as c,r as e,o as l,c as i,e as p,a as s,s as r,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"构建命令行命令 - October CMS - 3.x","titleTemplate":false,"description":"创建在控制台中运行的自定义命令。","frontmatter":{"subtitle":"创建在控制台中运行的自定义命令。"},"headers":[{"level":2,"title":"构建命令","slug":"构建命令","link":"#构建命令","children":[{"level":3,"title":"定义参数","slug":"定义参数","link":"#定义参数","children":[]},{"level":3,"title":"定义选项","slug":"定义选项","link":"#定义选项","children":[]},{"level":3,"title":"获取输入","slug":"获取输入","link":"#获取输入","children":[]},{"level":3,"title":"输出内容","slug":"输出内容","link":"#输出内容","children":[]}]},{"level":2,"title":"注册命令","slug":"注册命令","link":"#注册命令","children":[{"level":4,"title":"注册命令行命令","slug":"注册命令行命令","link":"#注册命令行命令","children":[]},{"level":4,"title":"在应用容器中注册命令","slug":"在应用容器中注册命令","link":"#在应用容器中注册命令","children":[]}]},{"level":2,"title":"调用其他命令","slug":"调用其他命令","link":"#调用其他命令","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/extend/console-commands.md","filePath":"3.x/zh-cn/extend/console-commands.md"}'),u={name:"3.x/zh-cn/extend/console-commands.md"};function d(k,n,g,h,m,v){const t=e("pre-heading"),o=e("post-heading");return l(),i("div",null,[p(t),n[0]||(n[0]=s("h1",null,"构建命令行命令",-1)),p(o),n[1]||(n[1]=r(`<p>要构建用于应用程序的自定义命令，请将它们存储在插件的 <strong>console</strong> 目录中。您可以使用命令行脚手架工具生成类文件。第一个参数指定作者和插件名称。第二个参数指定命令名称。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:command Acme.Blog MyCommand
</code></pre></div><h2 id="构建命令"><a href="#构建命令" class="header-anchor">#</a> 构建命令</h2><p>如果您想创建一个名为 <code>acme:mycommand</code> 的命令行命令，可以在名为 <strong>plugins/acme/blog/console/MyCommand.php</strong> 的文件中创建关联的类，并粘贴以下内容以开始使用：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Console</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Illuminate<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>Command</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Symfony<span class="token punctuation">\\</span>Component<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>Input<span class="token punctuation">\\</span>InputOption</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Symfony<span class="token punctuation">\\</span>Component<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>Input<span class="token punctuation">\\</span>InputArgument</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyCommand</span> <span class="token keyword">extends</span> <span class="token class-name">Command</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var string signature for the console command.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme:mycommand {user}&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var string description for the console command.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$description</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Does something cool.&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * handle executes the console command.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">handle</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$username</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">argument</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">output</span><span class="token operator">-&gt;</span><span class="token function">writeln</span><span class="token punctuation">(</span><span class="token string double-quoted-string">&quot;Hello <span class="token interpolation"><span class="token punctuation">{</span><span class="token variable">$username</span><span class="token punctuation">}</span></span>!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>类创建完成后，您应该填写类的 <code>signature</code> 和 <code>description</code> 属性，这些属性将在命令 <code>list</code> 屏幕上显示您的命令时使用。</p><p><code>handle</code> 方法将在执行命令时被调用。您可以在此方法中放置任何命令逻辑。</p><h3 id="定义参数"><a href="#定义参数" class="header-anchor">#</a> 定义参数</h3><p>所有用户提供的参数和选项都用花括号包裹在签名中。在以下示例中，命令定义了一个必需参数：user：</p><p>参数在签名中以花括号包裹的形式定义，您可以在其中定义命令接收的任何参数。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以通过在参数名称后添加问号（<code>?</code>）使参数变为可选。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user?}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，使用等号（<code>=</code>）后跟默认值来提供默认值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user=foo}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="定义选项"><a href="#定义选项" class="header-anchor">#</a> 定义选项</h3><p>选项与参数一样，是另一种用户输入形式，在签名中通过两个连字符（<code>--</code>）定义。选项可以选择性地接收一个值，如果没有值，它们将作为布尔开关值。例如，一个名为 <strong>queue</strong> 的开关值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--queue}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>在此示例中，调用命令时可以指定 <code>--queue</code> 开关。如果传递了 <code>--queue</code> 开关，选项的值将为 <code>true</code>。否则，值将为 <code>false</code>。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan mail:send <span class="token number">1</span> <span class="token parameter variable">--queue</span>
</code></pre></div><p>当选项需要一个值时，您应该在输入名称后加上等号（<code>=</code>）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--queue=}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>在这种情况下，选项可以接受一个值，否则值将为 <code>null</code>。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan mail:send <span class="token number">1</span> <span class="token parameter variable">--queue</span><span class="token operator">=</span>default
</code></pre></div><p>您也可以使用等号（<code>=</code>）后跟默认值来指定默认值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--queue=default}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>快捷方式是触发选项时的简短语法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--Q|queue}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>调用快捷方式时有一个重要区别。它应该以单个连字符（<code>-</code>）为前缀，并且不使用等号来提供值。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan mail:send <span class="token number">1</span> <span class="token parameter variable">-Qdefault</span>
</code></pre></div><h3 id="获取输入"><a href="#获取输入" class="header-anchor">#</a> 获取输入</h3><p>在命令执行期间，您显然需要访问应用程序接受的参数和选项的值。为此，您可以使用 <code>argument</code> 和 <code>option</code> 方法。</p><p>向 <code>argument</code> 方法提供名称以获取命令参数的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">argument</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>不提供名称时，将获取所有参数。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$arguments</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">argument</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>向 <code>option</code> 方法传递名称将获取命令选项的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">option</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>不提供名称时，将获取所有选项。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$options</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">option</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="输出内容"><a href="#输出内容" class="header-anchor">#</a> 输出内容</h3><p>要向控制台发送输出，您可以使用 <code>info</code>、<code>comment</code>、<code>question</code> 和 <code>error</code> 方法。每种方法都将使用适当的 ANSI 颜色来表达其用途。</p><p><code>info</code> 方法向用户发送信息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Display this on the screen&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>error</code> 方法用于发送错误消息。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Something went wrong!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以使用 <code>ask</code> 和 <code>confirm</code> 方法提示用户输入。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$name</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">ask</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;What is your name?&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>secret</code> 方法用于向用户询问秘密输入。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$password</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">secret</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;What is the password?&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>confirm</code> 方法要求用户确认，如果用户接受则返回 <code>true</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">confirm</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Do you wish to continue? [yes|no]&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以为 <code>confirm</code> 方法指定默认值，该值应为 <code>true</code> 或 <code>false</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">confirm</span><span class="token punctuation">(</span><span class="token variable">$question</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="注册命令"><a href="#注册命令" class="header-anchor">#</a> 注册命令</h2><h4 id="注册命令行命令"><a href="#注册命令行命令" class="header-anchor">#</a> 注册命令行命令</h4><p>命令类完成后，您需要注册它以便可以使用。这通常在<a href="./extending.html">插件注册文件</a>的 <code>register</code> 方法中使用 <code>registerConsoleCommand</code> 辅助方法完成。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Blog</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">pluginDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerConsoleCommand</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.mycommand&#39;</span><span class="token punctuation">,</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>MyConsoleCommand</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以使用它来放置命令注册逻辑。在此文件中，您可以使用 <code>Artisan::add</code> 方法注册命令。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>MyCommand</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="在应用容器中注册命令"><a href="#在应用容器中注册命令" class="header-anchor">#</a> 在应用容器中注册命令</h4><p>如果您的命令已注册到<a href="./services/application.html">应用容器</a>中，您可以使用 <code>Artisan::resolve</code> 方法使其对 Artisan 可用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;binding.name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="调用其他命令"><a href="#调用其他命令" class="header-anchor">#</a> 调用其他命令</h2><p>有时您可能希望从命令中调用其他命令。您可以使用 <code>call</code> 方法来实现。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october:migrate&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以以数组形式传递参数。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plugin:refresh&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;October.Demo&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>以及选项。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october:update&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;--force&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4>`,71)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"https://laravel.com/docs/10.x/artisan",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel Artisan 命令行文档"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const x=c(u,[["render",d]]);export{b as __pageData,x as default};
